// ===== validate input + build Gemini translate+spell request =====
// แอป (artwork_check/translate.py) ส่ง POST JSON {"lines": [...]}
const item = $input.first().json;
const body = item.body ?? item;

let lines = body.lines;
let valid = true;
let error = '';

if (!Array.isArray(lines)) {
  valid = false;
  error = "missing JSON field 'lines' (array of strings)";
  lines = [];
} else {
  lines = lines.map((l) => (l == null ? '' : String(l)));
  if (lines.length === 0) { valid = false; error = "'lines' is empty"; }
  if (lines.length > 400) {
    valid = false;
    error = `too many lines: ${lines.length} (limit 400)`;
  }
}

const PROMPT = [
  'You help proof food-packaging label text. You receive a JSON array of',
  'text lines in mixed languages (Arabic, Spanish, Thai, English, ...).',
  '',
  'For EACH input line, do TWO independent things:',
  '',
  '1) TRANSLATE to English -> array "translations":',
  '   - If a line is already English, return it unchanged.',
  '   - If a line is only digits / codes / units (e.g. "16785", "200 gm",',
  '     "70%"), return it unchanged.',
  '   - Translate the meaning faithfully and concisely. No notes, no comments.',
  '   - Do NOT correct spelling. Translate the text exactly as written,',
  '     including any misspellings.',
  '',
  '2) SPELL-CHECK the ORIGINAL line (advisory only) -> array "spell":',
  '   For each line return an object {"flagged": <bool>, "suggestion": <string|null>}.',
  '   - flagged = true ONLY if the ORIGINAL line clearly contains a real',
  '     typo / misspelling in its own language (wrong letters, swapped or',
  '     missing characters). Do NOT flag: correct words, brand names,',
  '     product names, valid loanwords, dialect spellings, abbreviations,',
  '     units, codes, or pure numbers.',
  '   - suggestion = the FULL corrected line when flagged=true; it MUST',
  '     differ from the original. If your correction equals the original,',
  '     set flagged=false and suggestion=null.',
  '   - If you are not fairly confident it is a typo, set flagged=false',
  '     and suggestion=null. Precision matters more than recall here.',
  '   - This NEVER affects pass/fail; it is a hint for a human reviewer.',
  '',
  'Output rules:',
  '   - "translations" and "spell" MUST each have EXACTLY the same number',
  '     of entries as the input array, in the SAME order (one per line).',
  '   - Return ONLY valid JSON, no markdown, no commentary:',
  '     {"translations": ["<en 1>", ...],',
  '      "spell": [{"flagged": false, "suggestion": null}, ...]}',
].join('\n');

const responseSchema = {
  type: 'OBJECT',
  properties: {
    translations: { type: 'ARRAY', items: { type: 'STRING' } },
    spell: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          flagged: { type: 'BOOLEAN' },
          suggestion: { type: 'STRING', nullable: true },
        },
        required: ['flagged'],
      },
    },
  },
  required: ['translations', 'spell'],
};

const geminiRequest = !valid ? null : {
  contents: [{
    role: 'user',
    parts: [
      { text: PROMPT },
      { text: 'INPUT LINES (JSON array):\n' + JSON.stringify(lines) },
    ],
  }],
  generationConfig: {
    temperature: 0,
    topP: 1,
    maxOutputTokens: 65536,
    responseMimeType: 'application/json',
    responseSchema,
    thinkingConfig: { thinkingBudget: 0 },
  },
};

// ส่ง lines + line_count ต่อให้ node parse ใช้ align/กรอง suggestion ซ้ำ
return [{
  json: {
    valid,
    error,
    line_count: lines.length,
    lines,
    gemini_request: geminiRequest,
  },
}];

// ===== parse Gemini response -> {"translations":[...], "spell":[...]} =====
const r = $input.first().json;
if (r.error) throw new Error(`Gemini API error: ${JSON.stringify(r.error)}`);

// ── ดึง input เดิมจาก node validate เพื่อ align ความยาว + กรอง suggestion ซ้ำ
const meta = $('Code in JavaScript2').first().json;
const srcLines = Array.isArray(meta.lines) ? meta.lines : [];
const n = Number.isInteger(meta.line_count) ? meta.line_count : srcLines.length;

// ── รวมข้อความตอบกลับจาก Gemini แล้วถอด ```json fences
const cand = (r.candidates ?? [])[0] ?? {};
const raw = ((cand.content ?? {}).parts ?? [])
  .map((p) => p.text ?? '').join('\n').trim();

let s = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let parsed = null;
try { parsed = JSON.parse(s); }
catch (e) {
  // เผื่อโมเดลแถมข้อความหุ้ม JSON: คว้าก้อน {...} ที่ใหญ่ที่สุด
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) {
    try { parsed = JSON.parse(s.slice(i, j + 1)); } catch (e2) {}
  }
}

const warnings = [];

// ── translations: รับได้ทั้ง {translations:[...]} และ array เปล่าๆ
let translations = [];
if (parsed && Array.isArray(parsed.translations)) {
  translations = parsed.translations;
} else if (Array.isArray(parsed)) {
  translations = parsed;
} else {
  warnings.push('model did not return a translations array');
}
translations = translations.map((t) => (t == null ? '' : String(t)));

// ── spell: normalize ให้เป็น {flagged, suggestion} เสมอ ไม่ว่าจะมารูปแบบไหน
const norm = (key) => key.toString().trim().toLowerCase();
let spell = [];
if (parsed && Array.isArray(parsed.spell)) {
  spell = parsed.spell.map((sp, idx) => {
    let flagged = false;
    let suggestion = null;
    if (sp && typeof sp === 'object' && !Array.isArray(sp)) {
      flagged = !!sp.flagged;
      suggestion = sp.suggestion != null ? String(sp.suggestion) : null;
    } else if (typeof sp === 'string') {
      // โมเดลคืนเป็น string ของคำที่แก้แล้ว
      suggestion = sp.trim() || null;
      flagged = !!suggestion;
    } else if (typeof sp === 'boolean') {
      flagged = sp;
    }
    // กรอง suggestion ที่ "ไม่ได้แก้อะไรจริง" (เหมือนต้นฉบับ) ทิ้ง
    const src = idx < srcLines.length ? srcLines[idx] : null;
    if (suggestion != null && src != null && norm(suggestion) === norm(src)) {
      suggestion = null;
    }
    // flagged=true แต่ไม่มี suggestion ที่ต่างจริง -> ลดเป็นไม่ flag
    if (flagged && suggestion == null) flagged = false;
    return { flagged, suggestion };
  });
} else if (parsed) {
  warnings.push('model did not return a spell array');
}

// ── บังคับความยาวให้ตรงกับจำนวนบรรทัด input (กัน model คืนเกิน/ขาด)
if (n > 0) {
  while (translations.length < n) translations.push('');
  translations.length = n;
  while (spell.length < n) spell.push({ flagged: false, suggestion: null });
  spell.length = n;
}

const warning = warnings.length ? warnings.join('; ') : undefined;

return [{
  json: {
    translations,
    spell,
    ...(warning ? { warning } : {}),
    usage: r.usageMetadata ?? null,
  },
}];
